'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// VARIABLES //

var quantile = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( quantile instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof quantile, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for `p`, the function returns `NaN`', opts, function test( t ) {
	var y = quantile( NaN, 20, 20, 10 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a number outside `[0,1]` for `p` and valid parameters, the function returns `NaN`', opts, function test( t ) {
	var y = quantile( 1.1, 20, 10, 10 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = quantile( -0.1, 20, 10, 10 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided an `N` which is not a nonnegative integer, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = quantile( 0.5, -2, 10, 5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.5, -1, 10, 5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a `K` which is not a nonnegative integer, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = quantile( 0.5, 20, -2, 5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.5, 20, -1, 5 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `n` which is not a nonnegative integer, the function returns `NaN`', opts, function test( t ) {
	var y;

	y = quantile( 0.5, 20, 5, -2 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = quantile( 0.5, 20, 5, -1 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'given valid parameters, the function returns `max( 0, n + K - N )` as the 0% quantile', opts, function test( t ) {
	var y = quantile( 0.0, 20, 10, 5 );
	t.strictEqual( y, 0, 'returns expected value' );

	y = quantile( 0.0, 20, 10, 15 );
	t.strictEqual( y, 5, 'returns expected value' );
	t.end();
});

tape( 'given valid parameters, the function returns `min( n, K )` as the 100% quantile', opts, function test( t ) {
	var y = quantile( 1.0, 30, 20, 15 );
	t.strictEqual( y, 15, 'returns expected value' );

	y = quantile( 1.0, 30, 20, 25 );
	t.strictEqual( y, 20, 'returns expected value' );

	y = quantile( 1.0, 30, 20, 5 );
	t.strictEqual( y, 5, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the quantile for `p` given valid parameters', opts, function test( t ) {
	var expected;
	var p;
	var N;
	var K;
	var n;
	var y;
	var i;

	expected = data.expected;
	p = data.p;
	N = data.N;
	K = data.K;
	n = data.n;
	for ( i = 0; i < p.length; i++ ) {
		y = quantile( p[i], N[i], K[i], n[i] );
		t.strictEqual( y, expected[i], 'p: '+p[i]+', N: '+N[i]+', K: '+K[i]+', n: '+n[i]+', y: '+y+', expected: '+expected[i] );
	}
	t.end();
});
